.truncate-single-line {
  max-width: 280px; /* Or use a percentage, e.g., 100% */
  overflow: hidden;
  white-space: nowrap;
  text-overflow: ellipsis; /* Displays '...' for truncated text */
  /* text-overflow: clip; /* Alternative: simply clips the text */
  display: inline-block; /* Or block, depending on context */
  vertical-align: top;
}
